/// <summary>
/// Copies a set of XAPI_APIConfigurations rows (identified by a container of API enum values)
/// into XAPI_TestCase rows under the given suite. Each selected API is appended as a new row
/// with Sequence = max(Sequence) + 10.
/// </summary>
/// <param name = "_suiteId">Target test suite identifier.</param>
/// <param name = "_apis">Container of XAPI_APIS enum values to copy.</param>
public static void copyMultiple(str _suiteId, container _apis)
{
    XAPI_APIConfigurations    config;
    XAPI_TestCase             testCase;
    int                       ncount;
    int                       i;
    XAPI_APIS                 api;

    ttsbegin;

    for (i = 1; i <= conLen(_apis); i++)
    {
        api = conPeek(_apis, i);

        select config
            where config.API == api;

        if (config.RecId)
        {
            int nextSeq;

            select maxof(Sequence) from testCase
                where testCase.SuiteId == _suiteId;

            nextSeq = max(testCase.Sequence + 10, 10);

            testCase.clear();
            testCase.SuiteId               = _suiteId;
            testCase.Sequence              = nextSeq;
            testCase.TestCaseId            = XAPI_TestSuiteCopyFromConfig::nextTestCaseId(_suiteId);
            testCase.API                   = api;
            testCase.URL                   = config.URL;
            testCase.JSON                  = config.JSON;
            testCase.PreProcessClass       = config.PreProcessClass;
            testCase.RunnerClass           = config.RunnerClass;
            testCase.PostProcessBatchClass = config.PostProcessBatchClass;
            testCase.Description           = config.Description;
            testCase.insert();

            ncount++;
        }
    }

    ttscommit;

    info(strFmt("Copied %1 API configs into suite %2.", ncount, _suiteId));
}

/// <summary>
/// For every test case in the given suite whose Description is blank,
/// looks up the matching XAPI_APIConfigurations row by API and copies
/// the Description across. Cases that already have a description are
/// left untouched.
/// </summary>
/// <param name = "_suiteId">Target test suite identifier.</param>
public static void backfillDescriptions(str _suiteId)
{
    XAPI_TestCase           testCase;
    XAPI_APIConfigurations  config;
    int                     ncount;

    ttsbegin;

    while select forupdate testCase
        where testCase.SuiteId == _suiteId
    {
        if (testCase.Description)
            continue;

        select config
            where config.API == testCase.API;

        if (config.RecId && config.Description)
        {
            testCase.Description = config.Description;
            testCase.update();
            ncount++;
        }
    }

    ttscommit;

    info(strFmt("Updated description for %1 test case(s) in suite %2.", ncount, _suiteId));
}

/// <summary>
/// Returns the next available TestCaseId for the given suite in the format "C###".
/// </summary>
public static str nextTestCaseId(str _suiteId)
{
    XAPI_TestCase   existing;
    int             maxNum = 0;
    int             currentId;
    int             padding;
    str             numStr;

    while select TestCaseId from existing
        where existing.SuiteId == _suiteId
    {
        if (existing.TestCaseId)
        {
            currentId = str2int(subStr(existing.TestCaseId, 2, strLen(existing.TestCaseId) - 1));
            if (currentId > maxNum)
            {
                maxNum = currentId;
            }
        }
    }

    maxNum++;
    numStr  = strFmt("%1", maxNum);
    padding = 3 - strLen(numStr);
    if (padding < 0)
    {
        padding = 0;
    }

    return "C" + subStr("000", 1, padding) + numStr;
}
